java-code-initials.solution:
class Solution {
    static String initials(String fullName) {
        StringBuilder sb = new StringBuilder();
        for (String word : fullName.trim().split(" +")) {
            if (!word.isEmpty()) {
                sb.append(Character.toUpperCase(word.charAt(0))).append('.');
            }
        }
        return sb.toString();
    }
}

