java-code-reverse-array.solution:
class Solution {
    static int[] reversed(int[] values) {
        int n = values.length;
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            out[i] = values[n - 1 - i];
        }
        return out;
    }
}

