class Solution {
    static String divide(String a, String b) {
        try {
            int x = Integer.parseInt(a);
            int y = Integer.parseInt(b);
            return String.valueOf(x / y);
        } catch (NumberFormatException e) {
            return "not a number";
        } catch (ArithmeticException e) {
            return "division by zero";
        }
    }
}

