java-code-generic-largest.solution:
import java.util.*;

class Solution {
    static <T extends Comparable<? super T>> T largest(List<? extends T> items) {
        if (items.isEmpty()) {
            throw new NoSuchElementException("empty list");
        }
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) {
                best = item;
            }
        }
        return best;
    }
}

