            return type.isInstance(e) ? null : "threw " + e + " but wanted " + type.getSimpleName();
        }
        return "no exception, wanted " + type.getSimpleName();
    }

    static Solution.Node build(int... vals) {
        Solution.Node head = null, tail = null;
        for (int v : vals) {
            Solution.Node n = new Solution.Node(v);
            if (head == null) { head = n; tail = n; } else { tail.next = n; tail = n; }
        }
        return head;
    }

    static String show(Solution.Node head) {
        StringBuilder sb = new StringBuilder();
        int guard = 0;
        for (Solution.Node n = head; n != null; n = n.next) {
            if (sb.length() > 0) sb.append(' ');
            sb.append(n.val);
            if (++guard > 100000) return "cycle detected";
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        t(() -> eq(show(Solution.reverse(build(1, 2, 3))), "3 2 1"));
        t(() -> eq(show(Solution.reverse(build())), ""));
        t(() -> eq(show(Solution.reverse(build(7))), "7"));
        t(() -> eq(show(Solution.reverse(build(1, 2))), "2 1"));
        t(() -> eq(show(Solution.reverse(build(5, 5, 9))), "9 5 5"));
        t(() -> eq(show(Solution.reverse(Solution.reverse(build(1, 2, 3, 4)))), "1 2 3 4"));
        t(() -> { Solution.Node h = build(1, 2, 3); Solution.Node last = h.next.next; return yes(Solution.reverse(h) == last, "must reuse the existing nodes: the old last node becomes the head"); });
        t(() -> { Solution.Node h = build(1, 2, 3); Solution.reverse(h); return yes(h.next == null, "the old head must become the tail"); });
        t(() -> { int[] v = new int[20000]; for (int i = 0; i < v.length; i++) v[i] = i; Solution.Node r = Solution.reverse(build(v)); return eq(r.val + " " + r.next.val, "19999 19998"); });
        t(() -> eq(show(Solution.reverse(build(-1, 0, 1, 0, -1))), "-1 0 1 0 -1"));
    }
}

