java-int-arithmetic.solution:
def java_arith(kind, a, op, b):
    bits = 32 if kind == "int" else 64

    def wrap(v):
        v &= (1 << bits) - 1
        return v - (1 << bits) if v >= 1 << (bits - 1) else v

    if op in "/%" and b == 0:
        return "ArithmeticException"
    if op == "+":
        r = a + b
    elif op == "-":
        r = a - b
    elif op == "*":
        r = a * b
    else:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        r = q if op == "/" else a - q * b
    return wrap(r)

