java-reference-model.solution:
def run_program(ops):
    heap = {}
    frame = {}
    out = []
    next_id = [1]

    def new_box(n):
        oid = next_id[0]
        next_id[0] += 1
        heap[oid] = n
        return oid

    for op in ops:
        kind = op[0]
        if kind == "new":
            frame[op[1]] = new_box(op[2])
        elif kind == "assign":
            frame[op[1]] = frame[op[2]]
        elif kind == "null":
            frame[op[1]] = None
        elif kind in ("set", "mutate"):
            ref = frame[op[1]]
            if ref is None:
                out.append("NullPointerException")
                break
            heap[ref] = op[2]
        elif kind == "reassign":
            new_box(op[2])
        elif kind == "swap":
            pass
        elif kind == "print":
            ref = frame[op[1]]
            if ref is None:
                out.append("NullPointerException")
                break
            out.append(heap[ref])
        elif kind == "same":
            out.append(frame[op[1]] == frame[op[2]])
    return out

java-casting-narrowing.solution:
def narrow(value, target):
    bits = {"byte": 8, "short": 16, "char": 16, "int": 32, "long": 64}[target]

    def clamp(v, b):
        lo, hi = -(1 << (b - 1)), (1 << (b - 1)) - 1
        return max(lo, min(hi, v))

    if isinstance(value, float):
        v = int(value)
        v = clamp(v, 64) if target == "long" else clamp(v, 32)
    else:
        v = value
    v &= (1 << bits) - 1
    if target != "char" and v >= 1 << (bits - 1):
        v -= 1 << bits
    return v

java-vault-feedback.solution:
def feedback(secret, guess):
    exact = sum(1 for s, g in zip(secret, guess) if s == g)
    left_s, left_g = {}, {}
    for s, g in zip(secret, guess):
        if s != g:
            left_s[s] = left_s.get(s, 0) + 1
            left_g[g] = left_g.get(g, 0) + 1
    near = sum(min(c, left_s.get(d, 0)) for d, c in left_g.items())
    return [exact, near]

