def grow(n, initial):
    default = initial == -1
    cap = 0 if default else initial
    size = growths = copied = 0
    for _ in range(n):
        if size == cap:
            if default and cap == 0:
                new_cap = 10
            else:
                new_cap = max(cap + cap // 2, cap + 1)
            copied += size
            cap = new_cap
            growths += 1
        size += 1
    return [cap, growths, copied]

