def init_order(classes, news):
    out = []
    loaded = set()

    def chain(name):
        c, path = name, []
        while c is not None:
            path.append(c)
            c = classes[c]["parent"]
        return path[::-1]

    for name in news:
        path = chain(name)
        for c in path:
            if c not in loaded:
                loaded.add(c)
                out.extend(c + "." + s for s in classes[c]["static"])
        for c in path:
            out.extend(c + "." + s for s in classes[c]["instance"])
            out.append(c + "." + classes[c]["ctor"])
    return out

