java-hashmap-sim.solution:
def hashmap_sim(capacity, load_factor, ops):
    def spread(k):
        h = k & 0xFFFFFFFF
        return h ^ (h >> 16)

    table = [[] for _ in range(capacity)]
    size = 0
    results = []
    for op in ops:
        k = op[1]
        h = spread(k)
        bucket = table[h & (len(table) - 1)]
        if op[0] == "put":
            for e in bucket:
                if e[0] == k:
                    e[1] = op[2]
                    break
            else:
                bucket.append([k, op[2]])
                size += 1
                if size > len(table) * load_factor:
                    old_n = len(table)
                    new_table = [[] for _ in range(2 * old_n)]
                    for i, b in enumerate(table):
                        for e in b:
                            new_table[i + old_n if spread(e[0]) & old_n else i].append(e)
                    table = new_table
        elif op[0] == "get":
            for e in bucket:
                if e[0] == k:
                    results.append(e[1])
                    break
            else:
                results.append(None)
        else:
            for idx, e in enumerate(bucket):
                if e[0] == k:
                    del bucket[idx]
                    size -= 1
                    break
    return [results, [[e[0] for e in b] for b in table]]

