def run_pipeline(data, ops):
    def jmod(a, b):
        r = abs(a) % abs(b)
        return -r if a < 0 else r

    xs = list(data)
    for op in ops:
        name = op[0]
        arg = op[1] if len(op) > 1 else None
        if name == "filter":
            if arg == "even":
                xs = [x for x in xs if x % 2 == 0]
            elif arg == "odd":
                xs = [x for x in xs if x % 2 != 0]
            elif arg == "positive":
                xs = [x for x in xs if x > 0]
            else:
                xs = [x for x in xs if x > arg[1]]
        elif name == "map":
            if arg == "square":
                xs = [x * x for x in xs]
            elif arg == "abs":
                xs = [abs(x) for x in xs]
            elif arg[0] == "mul":
                xs = [x * arg[1] for x in xs]
            else:
                xs = [x + arg[1] for x in xs]
        elif name == "flatMap":
            xs = [int(ch) for x in xs for ch in str(abs(x))]
        elif name == "distinct":
            seen, out = set(), []
            for x in xs:
                if x not in seen:
                    seen.add(x)
                    out.append(x)
            xs = out
        elif name == "sorted":
            xs = sorted(xs)
        elif name == "limit":
            xs = xs[:arg]
        elif name == "skip":
            xs = xs[arg:]
        elif name == "toList":
            return xs
        elif name == "count":
            return len(xs)
        elif name == "sum":
            return sum(xs)
        elif name == "groupingByCount":
            groups = {}
